export type DropdownMenuItemAction<T> = (event: React.MouseEvent<HTMLElement, MouseEvent> | KeyboardEvent, data?: T) => void;
type DropdownMenuItemWithActionProps<T> = {
    action: DropdownMenuItemAction<T>;
    href?: string;
    items?: DropdownMenuItemMixed<T>[];
};
